import os
import sqlite3
from flask import Flask, request, jsonify, g
import hashlib
import hmac
import time

app = Flask(__name__)
DATABASE = '/var/data/users.db'
SECRET_KEY = os.environ.get('HMAC_SECRET', 'default-dev-key')

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE,
        email TEXT,
        password_hash TEXT,
        role TEXT DEFAULT 'user',
        api_key TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        timestamp REAL,
        action TEXT,
        details TEXT
    )''')
    db.commit()
    db.close()

def verify_api_key(api_key):
    """Verify API key exists and return associated user"""
    db = get_db()
    cursor = db.execute('SELECT * FROM users WHERE api_key = ?', (api_key,))
    return cursor.fetchone()

def log_action(action, details):
    db = get_db()
    db.execute('INSERT INTO audit_log (timestamp, action, details) VALUES (?, ?, ?)',
               (time.time(), action, details))
    db.commit()

@app.route('/api/users/search', methods=['GET'])
def search_users():
    api_key = request.headers.get('X-API-Key')
    if not api_key:
        return jsonify({'error': 'Missing API key'}), 401

    caller = verify_api_key(api_key)
    if not caller:
        return jsonify({'error': 'Invalid API key'}), 403

    search_field = request.args.get('field', 'username')
    search_value = request.args.get('value', '')

    # Validate field name against allowed columns
    allowed_fields = ['username', 'email', 'role']
    if search_field not in allowed_fields:
        return jsonify({'error': 'Invalid search field'}), 400

    # Build query - field is validated above, value is user-controlled
    query = f"SELECT id, username, email, role FROM users WHERE {search_field} LIKE '%{search_value}%'"

    log_action('user_search', f'field={search_field}, value={search_value}, by={caller["username"]}')

    try:
        db = get_db()
        cursor = db.execute(query)
        results = [dict(row) for row in cursor.fetchall()]
        return jsonify({'results': results})
    except Exception as e:
        return jsonify({'error': 'Search failed', 'detail': str(e)}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    api_key = request.headers.get('X-API-Key')
    if not api_key:
        return jsonify({'error': 'Missing API key'}), 401

    caller = verify_api_key(api_key)
    if not caller:
        return jsonify({'error': 'Invalid API key'}), 403

    db = get_db()
    cursor = db.execute('SELECT id, username, email, role FROM users WHERE id = ?', (user_id,))
    user = cursor.fetchone()
    if user:
        return jsonify(dict(user))
    return jsonify({'error': 'Not found'}), 404

@app.route('/api/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.3.1'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
